        rs=[r for r in range(h) if g[r][c]==5]
        if len(rs)>=2 and all(rs[i+1]-rs[i]==1 for i in range(len(rs)-1)):
            bars.append(('v',min(rs),max(rs),c))
    barcells={(line,c) for t,a,b,line in bars for c in range(a,b+1)}
    seen=[[False]*w for _ in range(h)]
    bands=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=5 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]!=5 and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                bands.append(comp)
    def seqof(comp):
        rr=[r for r,_ in comp]; cc=[c for _,c in comp]
        r0=min(rr); c0=min(cc); r1=max(rr); c1=max(cc)
        if (r1-r0+1) >= (c1-c0+1):   # vertical band: seq down rows
            return ('v',(r0,c0),[g[r][c0] for r in range(r0,r1+1)], r1-r0+1)
        else:                          # horizontal band: per-row seq tiled down columns
            return ('h',(r0,c0),[[g[r0][c] for c in range(c0,c1+1)]], c1-c0+1)
    bandinfo=[]
    for comp in bands:
        info=seqof(comp)
        bandinfo.append(info)
    R0=min(r for r,_ in (barcells|set().union(*bands))); R1=max(r for r,_ in (barcells|set().union(*bands)))
    C0=min(c for _,c in (barcells|set().union(*bands))); C1=max(c for _,c in (barcells|set().union(*bands)))
    for r in range(R0,R1+1):
        for c in range(C0,C1+1):
            if (r,c) in barcells or any((r,c) in comp for comp in bands): continue
            best=None
            for typ,(br0,bc0),seq,p in bandinfo:
                d=min(abs(r-br0)+abs(c-bc0) for br,bc in [])
                # nearest by anchor distance instead
                dd=abs(r-br0)+abs(c-bc0)
                v = seq[(r-br0)%p] if typ=='v' else seq[(c-bc0)%p]
                if best is None or dd<best[0]: best=(dd,v,typ)
            if best: out[r][c]=best[1]
    return out

