from collections import deque
import json

def solve(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    bars=[]
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]==5]
        if len(cs)>=2 and all(cs[i+1]-cs[i]==1 for i in range(len(cs)-1)):
            bars.append(('h',r,min(cs),max(cs)))
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]==5]
        if len(rs)>=2 and all(rs[i+1]-rs[i]==1 for i in range(len(rs)-1)):
            bars.append(('v',c,min(rs),max(rs)))
    bset=set()
    for t_,l,a,b in bars:
        if t_=='h':
            for c in range(a,b+1): bset.add((l,c))
        else:
            for r in range(a,b+1): bset.add((r,l))
    seen=[[False]*w for _ in range(h)]
    bands=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] not in (0,5) and not seen[i][j]:
                q=deque([(i,j)]); comp=set()
                while q:
                    y,x=q.popleft(); comp.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx] not in (0,5) and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                bands.append(comp)
    R0,R1=min(r for r,_ in bset),max(r for r,_ in bset)
    C0,C1=min(c for _,c in bset),max(c for _,c in bset)
    for comp in bands:
        best=min(bars,key=lambda b:min(abs(r-b[1])+abs(c-(b[2] if b[0]=='h' else b[3])) for r,c in comp))
        _,t_,bl,bm=best
        D=[r for r,_ in comp]; D2=[c for _,c in comp]
        bh=max(D)-min(D)+1; bw=max(D2)-min(D2)+1
        bt=min(D); bl=min(D2)
        if bh>=bw:   # tall band: seq down rows, broadcast across fill columns
            seq=[g[r][bm] for r in range(bt,bt+bh)]
            for r in range(R0,R1+1):
                for c in range(C0,C1+1):
                    if (r,c) in bset or (r,c) in comp: continue
                    out[r][c]=seq[(r-bt)%bh]
        else:         # wide band: seq along rows, tile vertically
            seq=[[g[r][c] for c in range(bl,bl+bw)] for r in range(bt,bt+bh)]
            for r in range(R0,R1+1):
                for c in range(C0,C1+1):
                    if (r,c) in bset or (r,c) in comp: continue
                    out[r][c]=seq[(r-bt)%bh][(c-bl)%bw]
    return out

